import { ValidationResult } from './validation-result';
/**
 *
 * @param value - The string to validate.
 * @param condition - In the maxlength rule, the condition would be 10 to define that value.length < 10.
 * @param context - This can contain a parsed number so a maxValue validator will not have to parse the number again.
 */
export type ValidationFunction = (value: string, condition: any, context: {
    [key: string]: any;
}) => ValidationResult;
